Translate("ruRU", "gnarlpine-furbolgs", {
	title = "Фурболги Кривой Сосны",
	aliases = { "Кривая Сосна", "племя Кривой Сосны" },
	sections = {
		{
			title = "Обзор",
			text = [=[Кривая Сосна — племя {link:furbolgs}фурболгов{/link}, которые жили в холмах {link:teldrassil}Тельдрассил{/link}а как мирные друзья ночных эльфов. Они покинули свои старые дома и собрались под началом вождя {link:ursal-the-mauler}Урсал{/link}а Терзателя, и теперь нападают на тех самых защитников, которым некогда доверяли.]=],
		},
		{
			title = "Падение племени",
			text = [=[Дриада {link:tarindrella}Тариндрелла{/link} считает, что такую перемену мог вызвать только мох Скверны. {link:ursal-the-mauler}Урсал{/link} пользуется его силами, чтобы сводить свой народ с ума. Тотемы, оставленные в их брошенных лагерях, рассказывают больше. Фурболгам Кривой Сосны начала сниться великая тень, которая их уничтожит. Их страх обратился в ярость, а тень в их снах стала их друзьями-эльфами.]=],
		},
		{
			title = "Деяния безумия",
			text = [=[• Они напали из засады на стража {link:gaerolas-talvethren}Гаэролас{/link}а Талветрена и разграбили Деревню Звездного Ветра.
• Они вломились в {link:ban-ethil-barrow-den}Обитель Бен'этиль{/link}, и их шаманы научились отделять дух спящего друида от его тела.
• Они разбойничают на дороге в {link:darnassus}Дарнасс{/link} и нападают на дозоры у Прудов {link:pools-of-arlithrien}Арлитриэн{/link}а.
• Их мистик Ферокитас {link:chol-aruk}Пожиратель{/link} Снов украл изумруд, который черпал силу из Сна.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Никто пока не знает, откуда взялся мох Скверны и можно ли исцелить {link:furbolgs}фурболг{/link}ов.]=],
		},
	},
})

Translate("ruRU", "corruption-of-teldrassil", {
	title = "Порча Тельдрассила",
	sections = {
		{
			title = "Обзор",
			text = [=[Порча Тельдрассила — недуг, который расходится по новому Мировому Древу с тех пор, как его вырастили. Жрицы и друиды видят его знаки повсюду: в зверях, в растениях, в {link:furbolgs}фурболг{/link}ах и даже в почве.]=],
		},
		{
			title = "Знаки",
			text = [=[• Странные звери встают из самой земли древа, а древесники растут злобными и вздутыми от ядовитых опухолей.
• Мох Скверны пятнает греллей Тенистой долины, гарпий Поляны Оракула и {link:furbolgs}фурболг{/link}ов Кривой Сосны.
• Сатир Ксеторр Злобный исказил пауков древа, а другие {link:satyrs}сатир{/link}ы оскверняют его лунные колодцы.
• {link:lady-sathrah}Леди Сатра{/link}, паучиха, любимица богини Элуны, обезумела.
• Растения из далеких краев прорастают на древе и странно ведут себя в его почве.]=],
		},
		{
			title = "Вопрос о причине",
			text = [=[{link:corithras-moonrage}Коритрас Лунная Ярость{/link} возводит многие беды древа к тому, что его вырастили без благословения драконов Ноздорму и Алекстразы. {link:fandral-staghelm}Фэндрал Олений Шлем{/link} несет бремя поисков средства и боится, что его труд, возможно, никогда не будет окончен. Друиды Лунной поляны и {link:darnassus}Дарнасс{/link}а не доверяют друг другу, и непрекращающаяся порча ничуть не смягчает этого недоверия.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись пока не называет источник мха Скверны и не объясняет, как порча впервые проникла в древо.]=],
		},
	},
})
